import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Documentation site","description":"Adding component guides, generated API reference, local preview, and publishing","frontmatter":{"navigation":{"category":"Getting started"},"title":"Documentation site","description":"Adding component guides, generated API reference, local preview, and publishing","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/documentation-site.md"},"headers":[],"relativePath":"guides/documentation-site.md","filePath":"docs/documentation-site.md","lastUpdated":1792508673000}`),a={name:`guides/documentation-site.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to “Documentation site”">​</a></h1><p>Put repository-wide guides in <code>docs/</code> and component guides beside the component they explain. The site builds its navigation from those files and their metadata, then generates API references from source comments and action metadata. This guide shows where pages belong, how to organize them, and how to preview and publish the site.</p><h2 id="choose-where-a-page-belongs" tabindex="-1">Choose where a page belongs <a class="header-anchor" href="#choose-where-a-page-belongs" aria-label="Permalink to “Choose where a page belongs”">​</a></h2><p>Direct children of <code>docs/</code> are guides and appear under <code>/guides/</code>. Put reference pages in a folder, such as <code>docs/plugin-api/setup-and-build.md</code>, and they appear under <code>/docs/</code> with their folder structure. A nested <code>index.md</code> is the landing page for its folder. The repository home and Team page are exceptions: <code>docs/index.md</code> renders at <code>/</code>, and <code>docs/team.md</code> renders at <code>/team</code>. Neither is listed in the Guides or Docs catalog. Instructions for coding agents in <code>docs/agents/</code> stay in the repository and are not published.</p><p>For a plugin, put component-specific pages in <code>packages/&lt;plugin&gt;/docs/</code>; tools, actions and VS Code extensions use the same layout in their own folders. The site adds those pages to the component sidebar. If you create <code>docs/index.md</code>, it becomes the component&#39;s landing page and the README remains available as a separate <strong>README</strong> entry. Otherwise, the README is the overview when one exists; if it doesn&#39;t, the first docs page is used.</p><p>Write links from component docs to repository docs as relative Markdown links. <code>pnpm check</code> checks relative links, and the site rewrites those links to their site routes during the build. Source files and folders have no page on the site, so the build points relative links to them at GitHub. The build fails if a link points to a Markdown page the site doesn&#39;t publish, such as the root README or a benchmark page. Link a published page that covers the same ground, or use the file&#39;s GitHub URL.</p><h2 id="set-page-titles-and-navigation" tabindex="-1">Set page titles and navigation <a class="header-anchor" href="#set-page-titles-and-navigation" aria-label="Permalink to “Set page titles and navigation”">​</a></h2><p>Use frontmatter to control how a page appears in menus and sidebars:</p><ul><li><code>title</code> sets the menu and sidebar label. Without it, the first H1 is used; if there isn&#39;t one, the filename supplies the label.</li><li><code>description</code> supplies the short summary shown in menus and catalogs. Without it, the site derives a summary from the first prose paragraph.</li><li><code>navigation.category</code> groups direct-child guides. For nested docs, folders determine the groups; the nested <code>index.md</code> title labels its folder. Without an index, a category shared by the folder&#39;s pages can label it; otherwise, the site uses a readable version of the folder name.</li><li><code>navigation.type</code> accepts <code>link</code>, <code>card</code>, or <code>spotlight</code>. Pages are regular links by default; use <code>card</code> or <code>spotlight</code> when the page needs more visual emphasis.</li><li>On a component doc, <code>navigation.catalog: true</code> also lists the page in the repository-level Docs menu and catalog. It remains in the component sidebar.</li></ul><p>Component menu settings belong in a <code>docs.yml</code> file at the component root, next to <code>docs/</code>:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">navigation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    category</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Compatibility</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">card</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">artwork/plugin-mark.svg</span></span></code></pre></div><p><code>category</code> is optional; without it, the item stays in its default Plugins, Tools, or Actions group. VS Code extensions appear in the Tools menu, in a VS Code extensions group by default. <code>type</code> defaults to a regular link and can be set to <code>card</code> or <code>spotlight</code>. An <code>icon</code> path is relative to the component root. If you omit it—or the configured file doesn&#39;t exist—the site looks for <code>icon.svg</code>, <code>icon.png</code>, <code>icon.webp</code>, <code>logo.svg</code>, <code>logo.png</code>, or <code>logo.webp</code> first in the component root and then in <code>docs/</code>. The icon appears in navigation and beside the title on the component landing page.</p><p>To feature a plugin in the desktop Plugins menu, set <code>navigation.featured: true</code> on its <code>docs/index.md</code>. The menu has one featured-plugin area; the plugin remains in its normal category as well. The featured card uses the page title and package description. It uses the card style by default; set <code>navigation.type: spotlight</code> to make it a wide row.</p><h2 id="keep-the-catalog-and-readme-links-current" tabindex="-1">Keep the catalog and README links current <a class="header-anchor" href="#keep-the-catalog-and-readme-links-current" aria-label="Permalink to “Keep the catalog and README links current”">​</a></h2><p>The generated <code>docs/README.md</code> contains the Guides and Docs catalog; its introduction stays hand-written. Page metadata and folder names supply the catalog labels, while the root pages remain omitted. Run <code>pnpm readme</code> to refresh the catalog and generated README sections, or <code>pnpm readme:check</code> to check for drift without writing.</p><p>The <code>reference</code> block in a component README is also generated by <code>pnpm readme</code>. Its API URL comes from the component&#39;s discovered path, and a component guide link is added when <code>docs/index.md</code> exists. The public documentation base comes from the repository URL in the root <code>package.json</code>. Keep the generated markers in place and change the source metadata or docs files instead of maintaining those links by hand.</p><h2 id="add-api-documentation-at-its-source" tabindex="-1">Add API documentation at its source <a class="header-anchor" href="#add-api-documentation-at-its-source" aria-label="Permalink to “Add API documentation at its source”">​</a></h2><p>The API build generates pages from documented exports in plugin and tool source, action inputs and outputs in each action definition (<code>action.yml</code> or <code>action.yaml</code>), VS Code extension source, and exported repository script helpers. TypeDoc scans whole source folders, including implementation modules. <code>excludeNotDocumented</code> keeps symbols without JSDoc out of the reference; it doesn&#39;t check that every public API is documented. The JSDoc lint checks descriptions on exported TypeScript APIs.</p><p>Generated Pumpkin and WASI bindings can appear by name in public signatures, but their declarations aren&#39;t included as reference pages. The build generates the bindings before it runs TypeDoc. The generated API pages are build output and ignored by Git, so edit source comments, action metadata, or <code>typedoc.json</code> rather than editing those pages.</p><p>VitePress adds an <strong>Edit this page on GitHub</strong> link to Markdown pages. Generated API pages link to a corresponding source file when TypeDoc can identify one. The <strong>Last updated</strong> date comes from Git history; the docs workflow fetches full history so it can show the latest edit time for each page.</p><h2 id="keep-generated-site-details-in-mind" tabindex="-1">Keep generated site details in mind <a class="header-anchor" href="#keep-generated-site-details-in-mind" aria-label="Permalink to “Keep generated site details in mind”">​</a></h2><p>The site creates <code>/llms.txt</code> during the build from discovered guides, component docs, package and action metadata, and API references. Links to guides and component docs point to raw Markdown in the repository; API links point to the published docs site. The development server serves the same content at <code>/llms.txt</code>. Update source docs or metadata to change its entries, and <code>docs/.vitepress/llms.mts</code> to change its structure.</p><p>The <a href="/pumpkin-plugins/team">Team page</a> fetches all pages of contributor data from GitHub during builds and development, so the build needs network access and fails if GitHub is unavailable. It excludes bot accounts. Avatars, profile links, and contribution counts also come from GitHub, so there is no contributor list to maintain. If unauthenticated requests are rate limited, set <code>GITHUB_TOKEN</code> locally; the docs workflow supplies a read-only token. With a token, each contributor-list page can make at most one GraphQL request to look up public profile names. Without a token, or if name lookup fails, cards show GitHub usernames. The token and data loader aren&#39;t published with the cards.</p><p>The repository owner, taken from the repository URL in the root <code>package.json</code>, gets an Owner label and is sorted first; other contributors are sorted by contribution count. GitHub may take time to refresh those counts.</p><p>Plugin and action landing pages, READMEs, and API overview pages show native VitePress version badges. A badge reads its version from the package manifest or action version file. It links to a release only when the matching tag is present in the checkout. Release configuration supplies the tag name, and the workflow fetches tags with the full checkout.</p><h2 id="preview-build-and-publish" tabindex="-1">Preview, build, and publish <a class="header-anchor" href="#preview-build-and-publish" aria-label="Permalink to “Preview, build, and publish”">​</a></h2><p>While editing, run <code>pnpm run dev:docs</code> to generate the API pages and start the VitePress development server. To preview the last production build instead, run <code>pnpm run docs:preview</code>.</p><p>Build the complete site with <code>pnpm run docs</code>. It generates bindings, builds the API references, then builds the VitePress site. Bindings come from one Turbo <code>typecheck</code> run over plugin-kit, update-check, pumpkin-api, codemod and every plugin, so Turbo builds the plugin builder CLI first and a fresh clone needs no separate build step. TypeDoc runs before VitePress because the site reads its generated pages. <code>pnpm run docs:build</code> runs the same complete production build.</p><p>You can run the pipeline in stages: <code>pnpm run docs:types</code> generates binding declarations, <code>pnpm run docs:api</code> runs that step and then generates the API reference, and <code>pnpm run docs:site</code> builds the site from the generated pages. To generate one package&#39;s declarations, run <code>pnpm turbo run typecheck --filter=&lt;package&gt;</code>.</p><p>The <code>.github/workflows/docs.yml</code> workflow checks documentation on pull requests and publishes after pushes to <code>master</code> or <code>main</code>. It deploys a GitHub Pages artifact and mirrors the built files to the <code>gh-pages</code> branch. Set the repository&#39;s Pages source to <strong>GitHub Actions</strong>.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};